const vertex = `#version 300 es
in vec2 a_pos;
void main() { gl_Position = vec4(a_pos, 0.0, 1.0); }
`;

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.warn("[shader-canvas] shader compile failed:", gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

/** Builds a program that draws one fragment shader over a fullscreen triangle. */
export function createFullscreenProgram(gl: WebGL2RenderingContext, fragment: string, uniformNames: string[]) {
  const vs = compile(gl, gl.VERTEX_SHADER, vertex);
  const fs = compile(gl, gl.FRAGMENT_SHADER, fragment);
  if (!vs || !fs) {
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    return null;
  }

  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.warn("[shader-canvas] program link failed:", gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }

  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const location = gl.getAttribLocation(program, "a_pos");
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, 2, gl.FLOAT, false, 0, 0);
  gl.useProgram(program);

  const uniforms: Record<string, WebGLUniformLocation | null> = Object.fromEntries(
    uniformNames.map((name) => [name, gl.getUniformLocation(program, name)]),
  );

  return { program, buffer, uniforms };
}

.root {
  position: relative;
  isolation: isolate;
  display: inline-block;
  white-space: pre;
}
.word { display: inline-block; }
.canvas, .embers, .glow { position: absolute; pointer-events: none; }
.canvas {
  left: -.3em;
  top: -1em;
  width: calc(100% + .6em);
  height: calc(100% + 1.15em);
}
.root:has(.canvas[data-ready]) .word { color: transparent; }
.word::selection { background: Highlight; color: HighlightText; }
.glow {
  z-index: -1;
  inset: -8% -18%;
  background: radial-gradient(closest-side, color-mix(in srgb, var(--flame) 20%, transparent), transparent);
  filter: blur(.25em);
}
.embers { inset: 0; }
.spark {
  position: absolute;
  bottom: 30%;
  width: var(--size);
  height: var(--size);
  border-radius: 50%;
  background: color-mix(in srgb, var(--flame) 70%, #ffde94);
  box-shadow: 0 0 5px var(--flame);
  opacity: 0;
  animation: rise calc(var(--dur) / var(--burn-speed)) ease-out calc(var(--delay) / var(--burn-speed)) infinite;
}
.root[data-flame="candle"] .glow { opacity: .45; }
.root[data-flame="candle"] .spark { display: none; }
.root[data-flame="candle"] .spark:nth-child(4) {
  display: block;
  width: 2px;
  height: 2px;
  animation-duration: calc(5s / var(--burn-speed));
  --lift: -.65em;
}
@keyframes rise {
  0% { opacity: 0; transform: translate(0, 0) scale(1); }
  12% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--drift), var(--lift, -1.6em)) scale(.2); }
}
.root[data-still] .embers { display: none; }
@media (prefers-reduced-motion: reduce) {
  .embers { display: none; }
}
@media (forced-colors: active), print {
  .root:has(.canvas[data-ready]) .word { color: CanvasText; }
  .canvas, .embers, .glow { display: none; }
}

"use client";

import { cn } from "@/lib/utils";
import { useRef, type CSSProperties } from "react";
import styles from "./burning-text.module.css";
import { FlameCanvas } from "./flame-canvas";
import type { FlamePreset } from "./flame-shader";

export type { FlamePreset } from "./flame-shader";

/** Fixed spark layout so server and client render the same markup. */
const sparks = [
  { x: 10, size: 3, dur: 2.4, delay: 0, drift: -8 },
  { x: 22, size: 4, dur: 2.9, delay: 1.1, drift: 10 },
  { x: 35, size: 3, dur: 2.2, delay: 1.8, drift: -12 },
  { x: 48, size: 5, dur: 3.1, delay: 0.5, drift: 6 },
  { x: 60, size: 3, dur: 2.6, delay: 1.4, drift: -6 },
  { x: 72, size: 4, dur: 2.3, delay: 2.2, drift: 12 },
  { x: 85, size: 3, dur: 2.8, delay: 0.8, drift: -10 },
];

export type BurningTextProps = {
  children: string;
  /** Flame color; the whole palette derives from it. */
  color?: string;
  flame?: FlamePreset;
  sparks?: boolean;
  /** Freeze on a single frame (reduced motion always does). */
  still?: boolean;
  /** Flame animation speed multiplier; embers and glow follow it. */
  speed?: number;
  className?: string;
};

/**
 * Text that burns: WebGL flames rise from the real glyphs, the letters glow with a
 * slow rising heat gradient, and embers drift upward. The word stays real text.
 */
export function BurningText({ children, color = "#ff5b1f", flame = "campfire", sparks: showSparks = true, still = false, speed = 1, className }: BurningTextProps) {
  const textRef = useRef<HTMLSpanElement>(null);

  return (
    <span
      className={cn(styles.root, className)}
      data-flame={flame}
      data-still={still || undefined}
      style={{ "--flame": color, "--burn-speed": speed, color } as CSSProperties}
    >
      <span ref={textRef} className={styles.word}>{children}</span>
      {children.trim() && <>
        <span aria-hidden className={styles.glow} />
        <FlameCanvas textRef={textRef} text={children} color={color} preset={flame} still={still} speed={speed} />
      </>}
      {showSparks && children.trim() && (
        <span aria-hidden className={styles.embers}>
          {sparks.map((spark) => (
            <span
              key={spark.x}
              className={styles.spark}
              style={
                {
                  left: `${spark.x}%`,
                  "--size": `${spark.size}px`,
                  "--dur": `${spark.dur}s`,
                  "--delay": `${spark.delay}s`,
                  "--drift": `${spark.drift}px`,
                } as CSSProperties
              }
            />
          ))}
        </span>
      )}
    </span>
  );
}

/** How the flame bed follows the letters, in ems and as a slope (rise per unit across). */
export const bedShape = {
  /** How steeply the roof may fall away from a letter top; lower bridges more of a curve. */
  slope: 0.8,
  /** How far a letter top reaches sideways to bridge a dip. */
  reach: 0.5,
  /** Past the ends of the word, the fire fades out over this distance. */
  fade: 0.2,
};

const smoothstep = (edge0: number, edge1: number, value: number) => {
  const t = Math.min(Math.max((value - edge0) / (edge1 - edge0), 0), 1);
  return t * t * (3 - 2 * t);
};

/**
 * Measures where flames start in each pixel column of a glyph mask. The topmost ink in a
 * column is its letter top; a roof over those tops, which may fall away from each top at
 * `slope`, bridges the curved shoulders of round letters and the gaps between letters, so
 * fire rises along the whole word instead of only from flat tops.
 *
 * Returns RGBA floats per column, with heights as texture y (0 at the bottom, 1 at the top):
 * the roof, the letter top, the flame strength (fading past the word's ends) and the lowest ink.
 */
export function flameBed(alpha: Uint8ClampedArray, width: number, height: number, em: number) {
  const top = new Float64Array(width).fill(-1);
  const bottom = new Float64Array(width).fill(-1);
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      if (alpha[(y * width + x) * 4 + 3] > 127) {
        if (top[x] < 0) top[x] = y;
        bottom[x] = y;
      }
    }
  }

  const reach = Math.max(1, Math.round(bedShape.reach * em));
  const roof = new Float64Array(width).fill(-1);
  for (let x = 0; x < width; x++) {
    let best = Infinity;
    for (let d = -reach; d <= reach; d++) {
      const at = x + d;
      if (at < 0 || at >= width || top[at] < 0) continue;
      best = Math.min(best, top[at] + bedShape.slope * Math.abs(d));
    }
    if (best !== Infinity) roof[x] = best;
  }

  // Distance to the nearest inked column, so the fire fades out past the word's ends.
  const distance = new Float64Array(width).fill(Infinity);
  for (let x = 0, last = -Infinity; x < width; x++) {
    if (top[x] >= 0) last = x;
    distance[x] = x - last;
  }
  for (let x = width - 1, next = Infinity; x >= 0; x--) {
    if (top[x] >= 0) next = x;
    distance[x] = Math.min(distance[x], next - x);
  }

  const bed = new Float32Array(width * 4);
  const toTexture = (y: number) => 1 - (y + 0.5) / height;
  for (let x = 0; x < width; x++) {
    const inked = roof[x] >= 0;
    bed[x * 4] = inked ? toTexture(roof[x]) : 0;
    bed[x * 4 + 1] = top[x] >= 0 ? toTexture(top[x]) : 0;
    bed[x * 4 + 2] = inked ? 1 - smoothstep(0, bedShape.fade * em, distance[x]) : 0;
    bed[x * 4 + 3] = bottom[x] >= 0 ? toTexture(bottom[x]) : 0;
  }
  return bed;
}

"use client";

import { useEffect, useRef, type RefObject } from "react";
import { createFlameRenderer } from "./flame-renderer";
import type { FlamePreset } from "./flame-shader";
import styles from "./burning-text.module.css";

type Props = {
  textRef: RefObject<HTMLElement | null>;
  text: string;
  preset: FlamePreset;
  still: boolean;
  speed: number;
  color: string;
};

export function FlameCanvas({ textRef, text, preset, still, speed, color }: Props) {
  const ref = useRef<HTMLCanvasElement>(null);
  const options = useRef({ preset, still, speed });
  const invalidate = useRef<() => void>(undefined);

  useEffect(() => {
    options.current = { preset, still, speed };
    invalidate.current?.();
  }, [preset, still, speed, text, color]);

  useEffect(() => {
    const canvas = ref.current;
    const word = textRef.current;
    if (!canvas || !word) return;
    let renderer = createFlameRenderer(canvas, word);
    const reduced = matchMedia("(prefers-reduced-motion: reduce)");
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    let inView = false;
    let forceMask = true;
    let frame = 0;
    let time = 3;
    let last = 0;

    const animate = (now: number) => {
      time += Math.min(now - last, 50) / 1000 * options.current.speed;
      last = now;
      renderer?.draw(time);
      frame = requestAnimationFrame(animate);
    };
    const sync = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      if (!renderer || !inView || document.hidden) return;
      if (renderer.update(forceMask, options.current.preset)) {
        renderer.draw(time);
        canvas.dataset.ready = "";
      }
      forceMask = false;
      if (!reduced.matches && !options.current.still) {
        last = performance.now();
        frame = requestAnimationFrame(animate);
      }
    };
    const fontsChanged = () => { forceMask = true; sync(); };
    const lost = (event: Event) => {
      event.preventDefault();
      renderer = undefined;
      delete canvas.dataset.ready;
      sync();
    };
    const restored = () => {
      renderer = createFlameRenderer(canvas, word);
      fontsChanged();
    };
    invalidate.current = sync;
    const resize = new ResizeObserver(sync);
    resize.observe(word);
    resize.observe(canvas);
    const theme = new MutationObserver(sync);
    for (let node = canvas.parentElement; node; node = node.parentElement) {
      theme.observe(node, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    }
    const viewer = new IntersectionObserver(([entry]) => {
      inView = entry.isIntersecting;
      sync();
    });
    viewer.observe(canvas);
    document.fonts?.addEventListener("loadingdone", fontsChanged);
    document.addEventListener("visibilitychange", sync);
    window.addEventListener("resize", sync);
    reduced.addEventListener("change", sync);
    scheme.addEventListener("change", sync);
    canvas.addEventListener("webglcontextlost", lost);
    canvas.addEventListener("webglcontextrestored", restored);
    return () => {
      invalidate.current = undefined;
      cancelAnimationFrame(frame);
      resize.disconnect();
      theme.disconnect();
      viewer.disconnect();
      document.fonts?.removeEventListener("loadingdone", fontsChanged);
      document.removeEventListener("visibilitychange", sync);
      window.removeEventListener("resize", sync);
      reduced.removeEventListener("change", sync);
      scheme.removeEventListener("change", sync);
      canvas.removeEventListener("webglcontextlost", lost);
      canvas.removeEventListener("webglcontextrestored", restored);
      renderer?.dispose();
      delete canvas.dataset.ready;
    };
  }, [textRef]);

  return <canvas ref={ref} aria-hidden className={styles.canvas} />;
}

import { flameBed } from "./flame-bed";
import { flamePresets, flameShader, flameUniforms, type FlamePreset } from "./flame-shader";
import { createFullscreenProgram } from "./burning-text-gl";

export function createFlameRenderer(canvas: HTMLCanvasElement, word: HTMLElement) {
  const gl = canvas.getContext("webgl2", { alpha: true, antialias: false, premultipliedAlpha: true });
  const mask = document.createElement("canvas");
  const ctx = mask.getContext("2d", { willReadFrequently: true });
  if (!gl || !ctx) return;
  const setup = createFullscreenProgram(gl, flameShader, flameUniforms);
  if (!setup) return;
  const u = setup.uniforms;

  const texture = (unit: number, uniform: string) => {
    const handle = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, handle);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.uniform1i(u[uniform], unit);
    return handle;
  };

  const glyphs = texture(0, "u_mask");
  const bed = texture(1, "u_bed");
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  let geometry = "";
  let palette = "";

  return {
    update(forceMask: boolean, preset: FlamePreset) {
      const style = getComputedStyle(word);
      const box = canvas.getBoundingClientRect();
      const letters = word.getBoundingClientRect();
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
      const text = word.textContent ?? "";
      const x = letters.left - box.left;
      const y = letters.top - box.top;
      const key = JSON.stringify([text, font, style.letterSpacing, style.direction, box.width, box.height, x, y, letters.height, dpr]);
      const maskChanged = forceMask || key !== geometry;
      if (maskChanged) {
        geometry = key;
        canvas.width = mask.width = Math.max(1, Math.round(box.width * dpr));
        canvas.height = mask.height = Math.max(1, Math.round(box.height * dpr));
        gl.viewport(0, 0, mask.width, mask.height);
        gl.uniform2f(u.u_res, mask.width, mask.height);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.font = font;
        ctx.direction = style.direction === "rtl" ? "rtl" : "ltr";
        ctx.textAlign = "left";
        ctx.letterSpacing = style.letterSpacing === "normal" ? "0px" : style.letterSpacing;
        const metrics = ctx.measureText(text);
        const baseline = y + (letters.height + metrics.fontBoundingBoxAscent - metrics.fontBoundingBoxDescent) / 2;
        ctx.fillStyle = "#fff";
        ctx.fillText(text, x, baseline);
        gl.activeTexture(gl.TEXTURE0);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, mask);
        const em = parseFloat(style.fontSize) * dpr;
        const pixels = ctx.getImageData(0, 0, mask.width, mask.height).data;
        gl.activeTexture(gl.TEXTURE1);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, mask.width, 1, 0, gl.RGBA, gl.FLOAT, flameBed(pixels, mask.width, mask.height, em));
        gl.uniform1f(u.u_em, em / mask.height);
      }
      const { color, colorScheme } = getComputedStyle(canvas);
      const paletteKey = JSON.stringify([color, colorScheme, preset]);
      if (paletteKey === palette) return maskChanged;
      palette = paletteKey;
      // Canvas resolves CSS colors, including wide-gamut theme tokens, to sRGB bytes.
      ctx.resetTransform();
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 1, 1);
      const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data;
      gl.uniform3f(u.u_color, r / 255, g / 255, b / 255);
      gl.uniform1f(u.u_dark, colorScheme === "dark" ? 1 : 0);
      const { reach, sway, rate, profile } = flamePresets[preset];
      gl.uniform1f(u.u_reach, reach);
      gl.uniform1f(u.u_sway, sway);
      gl.uniform1f(u.u_rate, rate);
      gl.uniform1f(u.u_profile, profile);
      return true;
    },
    draw(time: number) {
      gl.uniform1f(u.u_time, time);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    dispose() {
      gl.deleteTexture(glyphs);
      gl.deleteTexture(bed);
      gl.deleteBuffer(setup.buffer);
      gl.deleteProgram(setup.program);
    },
  };
}

export const flameUniforms = ["u_mask", "u_bed", "u_res", "u_time", "u_color", "u_dark", "u_reach", "u_sway", "u_rate", "u_profile", "u_em"];

/** Presets for how tall, wild and fast the flames are. */
export const flamePresets = {
  candle: { reach: 0.085, sway: 0.012, rate: 0.52, profile: -1 },
  campfire: { reach: 0.21, sway: 0.05, rate: 1.05, profile: 0 },
  blaze: { reach: 0.40, sway: 0.085, rate: 1.38, profile: 1 },
} as const;

export type FlamePreset = keyof typeof flamePresets;

/**
 * Flames rising from a glyph mask. `u_bed` holds, per column, a roof over the letter tops
 * (see flame-bed.ts), the letter top and the flame strength. Flames rise from the roof with
 * noise-driven sway that grows with height; below the roof, down to the letters, the bed
 * burns too, so fire fills curved shoulders and the dips between letters.
 */
export const flameShader = /* glsl */ `#version 300 es
precision highp float;
uniform sampler2D u_mask;
uniform sampler2D u_bed;
uniform vec2 u_res;
uniform float u_time;
uniform vec3 u_color;
uniform float u_dark;
uniform float u_reach;
uniform float u_sway;
uniform float u_rate;
uniform float u_profile;
uniform float u_em;
out vec4 outColor;
float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;
  float t = u_time * u_rate;

  // Flow field scrolling upward: sways and stretches the flames.
  vec2 flow = vec2(uv.x * aspect * 2.4, uv.y * 2.0 - t * 1.25);
  float n1 = fbm(flow);
  float n2 = fbm(flow * 2.3 + vec2(3.7, -t * 1.1));
  float reach = u_reach * (0.55 + 0.9 * n1);

  // Sway grows with height above the roof, so the base stays on the letters.
  float rise = clamp((uv.y - texture(u_bed, vec2(uv.x, 0.5)).r) / reach, 0.0, 1.0);
  float shift = ((n1 - 0.5) + (n2 - 0.5) * 0.7) * u_sway * rise * 1.6;
  vec3 bed = texture(u_bed, vec2(uv.x - shift, 0.5)).rgb;
  // Candle has only a few low flickers on the actual letter tops.
  if (u_profile < 0.0) {
    bed.b *= 1.0 - smoothstep(0.06, 0.16, (bed.r - bed.g) / u_em);
    bed.r = max(bed.g, bed.r - 0.16 * u_em);
    bed.b *= mix(0.42, 1.0, smoothstep(0.26, 0.70, n2));
  }
  float above = uv.y - bed.r;
  // Tongues rise tallest straight off the letters and stay lower over the gaps between them.
  reach *= mix(0.78, 1.15, bed.b);

  // Run one heat field through the upper strokes and into the air above them.
  // Only the lower part of the word returns to solid ink.
  float ink = texture(u_mask, uv).a;
  float root = max(bed.g, bed.r - 0.14 * u_em);
  float belowTop = max(root - uv.y, 0.0) / u_em;
  float licks = smoothstep(0.26, 0.74, fbm(vec2(uv.x * aspect * 7.0, uv.y * 3.0 - t * 2.2)));
  float inside = 1.0 - smoothstep(0.01, 0.13 + 0.13 * licks, belowTop);
  float crown = 1.0 - smoothstep(0.06, 0.23, max(-above, 0.0) / u_em);
  float heat = pow(max(1.0 - max(above, 0.0) / reach, 0.0), 0.9);
  heat *= bed.b * crown * inside;
  float fire = heat * mix(0.48, 1.16, licks);

  if (u_profile < 0.0) {
    fire *= 0.84;
  } else if (u_profile > 0.0) {
    // Follow each column from its lowest ink. The glyph mask keeps the
    // counters open while hot streaks climb the strokes into the plume.
    vec4 column = texture(u_bed, vec2(uv.x, 0.5));
    float height = max(column.g - column.a, 1.0 / u_res.y);
    float fromBase = clamp((uv.y - column.a) / height, 0.0, 1.0);
    float streak = fbm(vec2(uv.x * aspect * 10.0 + 1.3 * n2, uv.y * 4.0 - t * 2.5));
    float ignition = mix(0.52, 1.38, smoothstep(0.24, 0.74, streak));
    fire = max(fire * 1.18, ink * ignition * mix(1.10, 0.92, fromBase));
  }

  vec3 coal = u_color * mix(0.63, 0.88, u_dark);
  float warmth = smoothstep(0.0, 0.55, u_color.r - u_color.b);
  vec3 incandescent = mix(vec3(0.88, 0.95, 1.0), vec3(1.0, 0.79, 0.42), warmth);
  vec3 ember = mix(u_color, incandescent, 0.55);
  vec3 flame = mix(u_color, ember, smoothstep(0.46, 0.88, fire));
  flame = mix(flame, mix(incandescent, vec3(1.0), 0.6), 0.5 * smoothstep(0.84, 1.12, fire));
  vec3 body = mix(coal, mix(u_color, ember, 0.45 * u_dark), 0.28 + 0.65 * licks);
  body = mix(body, incandescent, 0.12 * u_dark * smoothstep(0.10, 0.30, belowTop));
  body = mix(body, flame, inside * crown);
  // At a hot root the same color covers both sides of the glyph silhouette.
  float plume = smoothstep(0.18, 0.80, fire) * (1.0 - smoothstep(0.85, 1.0, uv.y));
  outColor = vec4(mix(body * ink, flame, plume), ink + (1.0 - ink) * plume);
}
